<?php
if (!defined('ABSPATH')) { exit; }
if (!defined('DONOTCACHEPAGE')) { define('DONOTCACHEPAGE', true); } nocache_headers();
$action = isset($_GET['mail_action']) && is_string($_GET['mail_action']) ? sanitize_key($_GET['mail_action']) : '';
$id = absint($_GET['subscriber'] ?? 0); $token = isset($_GET['token']) && is_string($_GET['token']) ? wp_unslash($_GET['token']) : '';
$notice = isset($_GET['notice']) && is_string($_GET['notice']) ? sanitize_key($_GET['notice']) : '';
$messages = ['sent' => '如果该邮箱尚未订阅，确认邮件将发送到你的邮箱。请打开邮件链接并确认。', 'confirmed' => '订阅已确认，之后会收到新文章通知。', 'unsubscribed' => '已退订，之后不会再向该邮箱发送新文章通知。', 'email' => '请填写有效的邮箱地址。', 'consent' => '请先同意接收邮件。', 'rate' => '操作过于频繁，请稍后再试。', 'mail' => '暂时无法发送确认邮件，请稍后再试。', 'disabled' => '邮件订阅尚未启用。', 'token' => '链接无效或已过期，请重新订阅。', 'spam' => '校验未通过，请刷新重试。', 'storage' => '暂时无法保存，请稍后再试。'];
get_header(); ?>
<div class="site-layout reading-layout"><?php get_template_part('template-parts/rail'); ?><main id="main-content" class="reading-main"><section class="submission-page newsletter-page"><span class="eyebrow">GOOD DISCOVERIES, DELIVERED</span><h1><?php echo esc_html(dh_opt('mail_title')); ?></h1><p class="submission-lead"><?php echo nl2br(esc_html(dh_opt('mail_description'))); ?></p>
<?php if (isset($messages[$notice])): ?><p class="newsletter-notice" role="status"><?php echo esc_html($messages[$notice]); ?></p><?php endif; ?>
<?php if (in_array($action, ['confirm', 'unsubscribe'], true)): $valid = dh_newsletter_token_action($id, $token, $action); if (is_wp_error($valid)): ?><p class="submission-error"><?php echo esc_html($valid->get_error_message()); ?></p>
<?php else: ?><div class="submission-success"><h2><?php echo $action === 'confirm' ? '确认接收邮件' : '确认取消订阅'; ?></h2><p><?php echo $action === 'confirm' ? '点击下面的按钮完成订阅确认。' : '确认后不再接收本站的新文章邮件。'; ?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="dh_mail_action"><input type="hidden" name="mail_action" value="<?php echo esc_attr($action); ?>"><input type="hidden" name="subscriber" value="<?php echo esc_attr($id); ?>"><input type="hidden" name="token" value="<?php echo esc_attr($token); ?>"><?php wp_nonce_field('dh_mail_action', 'dh_mail_nonce'); ?><button class="button" type="submit"><?php echo $action === 'confirm' ? '确认订阅' : '确认退订'; ?></button></form></div><?php endif; ?>
<?php elseif (dh_opt('mail_enabled')): ?><form class="submission-form newsletter-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="dh_subscribe"><?php wp_nonce_field('dh_subscribe', 'dh_subscribe_nonce'); ?><div class="submission-honeypot" aria-hidden="true"><input name="newsletter[website_check]" tabindex="-1" autocomplete="off"></div><p><label for="newsletter-email">邮箱地址</label><input type="email" id="newsletter-email" name="newsletter[email]" maxlength="190" autocomplete="email" required placeholder="you@example.com"></p><p class="newsletter-consent"><label><input type="checkbox" name="newsletter[consent]" value="1" required> 我同意接收新文章邮件，知道可以通过邮件中的链接随时退订。</label></p><button class="button" type="submit">发送确认邮件 <?php echo dh_icon('arrow'); ?></button><p class="section-caption">只有确认邮箱后才会开始通知；不会公开你的邮箱地址。</p></form>
<?php else: ?><p class="newsletter-notice">邮件订阅暂未启用。</p><?php endif; ?></section></main><?php get_template_part('template-parts/sidebar'); ?></div><?php get_footer(); ?>
